/* Marquee Slide to Left */
@keyframes slideLeftHalf {
0% { transform: translateX(0%); }
100% { transform: translateX(-50%); }
}
/* Marquee Slide to Right */
@keyframes slideRightHalf {
0% { transform: translateX(0%); }
